import{_ as e,o as t,c as l,a2 as n}from"./chunks/framework.ClgMjOt7.js";const y=JSON.parse('{"title":"PallaSync データ同期 & 同期サーバー","description":"設定・状態の端末間同期機能、暗号化アーキテクチャ、同期サーバー仕様","frontmatter":{"title":"PallaSync データ同期 & 同期サーバー","description":"設定・状態の端末間同期機能、暗号化アーキテクチャ、同期サーバー仕様"},"headers":[],"relativePath":"features/sync.md","filePath":"features/sync.md","lastUpdated":1786168778000}'),s={name:"features/sync.md"};function o(i,a,c,r,p,d){return t(),l("div",null,[...a[0]||(a[0]=[n(`<h1 id="pallasync-データ同期-同期サーバー" tabindex="-1">PallaSync データ同期 &amp; 同期サーバー <a class="header-anchor" href="#pallasync-データ同期-同期サーバー" aria-label="Permalink to &quot;PallaSync データ同期 &amp; 同期サーバー&quot;">​</a></h1><p>PallaSync は、複数端末間でアプリの設定、お気に入りタグ（ウォッチリスト）、およびアプリ状態を安全にバックアップ・同期するための機能です。</p><hr><h2 id="主な特徴" tabindex="-1">主な特徴 <a class="header-anchor" href="#主な特徴" aria-label="Permalink to &quot;主な特徴&quot;">​</a></h2><ul><li><strong>エンドツーエンド類似の安全な暗号化</strong>: データは送信前に端末上で AES-256-GCM 暗号化されるため、サーバー側で平文データが閲覧・解読されることはありません。</li><li><strong>バックグラウンド同期</strong>: アプリ起動時およびバックグラウンドで自動的に変更イベントを検知・同期。</li><li><strong>自動競合解決 (Conflict Resolution)</strong>: 複数デバイスで同時に変更が行われた場合、タイムスタンプに基づく LWW (Last-Write-Wins) ロジックで競合を自動処理。</li></ul><hr><h2 id="システム構成-データフロー" tabindex="-1">システム構成 &amp; データフロー <a class="header-anchor" href="#システム構成-データフロー" aria-label="Permalink to &quot;システム構成 &amp; データフロー&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> [ Palleria アプリ (端末 A) ]</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── 1. 変更イベント発生 (設定 / お気に入りタグ等)</span></span>
<span class="line"><span>        ├── 2. Android KeyStore で AES-256-GCM 暗号化 (PallaSyncKeystore)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼ 3. HTTPS 通信 (Encrypted Payload)</span></span>
<span class="line"><span> [ PallaSync 同期サーバー (https://api.yunfi.f5.si) ]</span></span>
<span class="line"><span>        ▲</span></span>
<span class="line"><span>        │ 4. 暗号化データの同期取得</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span> [ Palleria アプリ (端末 B) ]</span></span>
<span class="line"><span>        ├── 5. ローカル KeyStore 鍵で復号</span></span>
<span class="line"><span>        └── 6. LWW 競合解決 (PallaSyncConflictResolver) ──&gt; DataStore / Room DB へ反映</span></span></code></pre></div><hr><h2 id="仕様パラメータ-設定項目-appsettings" tabindex="-1">仕様パラメータ &amp; 設定項目 (<code>AppSettings</code>) <a class="header-anchor" href="#仕様パラメータ-設定項目-appsettings" aria-label="Permalink to &quot;仕様パラメータ &amp; 設定項目 (\`AppSettings\`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">設定キー</th><th style="text-align:left;">型</th><th style="text-align:left;">デフォルト値</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>pallaSyncEnabled</code></td><td style="text-align:left;"><code>Boolean</code></td><td style="text-align:left;"><code>false</code></td><td style="text-align:left;">PallaSync 同期機能の有効化</td></tr><tr><td style="text-align:left;"><code>pallaSyncServerUrl</code></td><td style="text-align:left;"><code>String</code></td><td style="text-align:left;"><code>&quot;https://api.yunfi.f5.si&quot;</code></td><td style="text-align:left;">使用する PallaSync 同期サーバーの Endpoint URL</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">セルフホスト対応</p><p>デフォルトでは公式同期サーバー (<code>https://api.yunfi.f5.si</code>) を使用しますが、独自に立ち上げた PallaSync 互換サーバーの URL を指定してセルフホスト運用することも可能です。</p></div><hr><h2 id="内部コンポーネント詳細" tabindex="-1">内部コンポーネント詳細 <a class="header-anchor" href="#内部コンポーネント詳細" aria-label="Permalink to &quot;内部コンポーネント詳細&quot;">​</a></h2><h3 id="_1-palleriasyncmanager" tabindex="-1">1. <code>PalleriaSyncManager</code> <a class="header-anchor" href="#_1-palleriasyncmanager" aria-label="Permalink to &quot;1. \`PalleriaSyncManager\`&quot;">​</a></h3><p>アプリケーションプロセス内で単一インスタンスとして管理される同期コーディネーターです。</p><ul><li><code>startBackgroundSync()</code>: バックグラウンドでの定期同期ジョブを起動。</li><li><code>recoverInterruptedActivation()</code>: ネットワーク一時断などで中断された同期アクティベーションの自動復旧。</li></ul><h3 id="_2-pallasynckeystore" tabindex="-1">2. <code>PallaSyncKeystore</code> <a class="header-anchor" href="#_2-pallasynckeystore" aria-label="Permalink to &quot;2. \`PallaSyncKeystore\`&quot;">​</a></h3><p>暗号化鍵のライフサイクルを管理します。</p><ul><li><code>AndroidKeyStore</code> から 256 ビット AES 鍵を取得/生成。</li><li>データごとにユニークな 12 バイト初期化ベクター (IV) と 16 バイト GCM 認証タグを生成して改ざん防止。</li></ul><h3 id="_3-pallasyncconflictresolver" tabindex="-1">3. <code>PallaSyncConflictResolver</code> <a class="header-anchor" href="#_3-pallasyncconflictresolver" aria-label="Permalink to &quot;3. \`PallaSyncConflictResolver\`&quot;">​</a></h3><p>ローカルとリモートで同一項目の変更が競合した場合、各イベントに付与されたミリ秒精度タイムスタンプを比較し、最も新しい変更（Last-Write-Wins）を安全に採用します。</p><h3 id="_4-pallasynceventapplier" tabindex="-1">4. <code>PallaSyncEventApplier</code> <a class="header-anchor" href="#_4-pallasynceventapplier" aria-label="Permalink to &quot;4. \`PallaSyncEventApplier\`&quot;">​</a></h3><p>同期されたイベント（<code>PallaSyncSettingsEvents</code>）を読み込み、ローカルの <code>DataStore</code>（設定）および Room DB（<code>FavoriteTagEntity</code> 等）へ非同期で反映させます。</p>`,24)])])}const u=e(s,[["render",o]]);export{y as __pageData,u as default};
